    let best = lake.pts[0];
    for (const p of lake.pts) if (Math.hypot(p[0] - towerPos.x, p[1] - towerPos.z) < Math.hypot(best[0] - towerPos.x, best[1] - towerPos.z)) best = p;
    const dir = V(best[0] - cx, 0, best[1] - cz);
