      mallet.visible = false;
      const hs = t < 1.2 ? lerp2(0, -0.8, t / 1.2) : lerp2(-0.8, 2.3, clamp01((t - 1.9) / 0.18));
      hMallet.rotation.x = hs;
      for (const a of H.rig.arms) {
        a.sh.rotation.set(hs - Math.PI, 0, 0);
        a.el.rotation.x = -0.1;
      }
      puckF = t < 2.1 ? 0 : Math.min(0.75, (t - 2.1) * 3);
