  const S = actor(K, I, CAST.sherpa, { vest: "#ff8a1f" });
  const flask = makeFlask(I.bag, 1.2);
  root.add(flask);
  const flag = makeFlag(I.bag, "SUMMIT!", "#ff3d8b");
  root.add(flag.root);
  const snowM = I.bag.mat("#ffffff");
  const drifts = [];
  for (let i = 0; i < 14; i++) {
    const l = (i % 2 ? 1 : -1) * (PATH_W / 2 + 1.2 + i % 5 * 1.6), a = -8 + i * 2.3 % 18;
    const d = I.bag.M(new SphereGeometry(1, 12, 8).scale(1.6 + i % 3 * 0.6, 0.5, 1.2), snowM, 2.5);
    d.position.copy(f1.p(a, l, -0.3));
    root.add(d);
    drifts.push(d);
  }
  const cap = I.bag.M(new CylinderGeometry(PATH_W / 2 + 0.6, PATH_W / 2 + 0.6, 0.12, 20), snowM, 0);
  cap.position.copy(f1.p(0, 0, -0.13));
