  mirror.add(glass);
  const blink = new Mesh(I.bag.add(new SphereGeometry(0.14, 10, 8)), I.bag.basic("#ff9a1f"));
  const parp = sprite(I.bag, bubbleTexture(I.bag, "PARP PARP!", { w: 640, h: 280, size: 110, bg: "#ffffff" }), 0.9, 640 / 280);
  root.add(parp);
